insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_85_v1'
from (values
('127.683.d.1.A',3,'A video editor, a graphic designer and a sound technician are examples of:','["jobs in digital media", "jobs in farming", "jobs in plumbing", "jobs in mining"]'::jsonb,0,'These careers create digital media.','original'),
('127.683.d.1.A',4,'Which task would a motion graphics artist most likely perform?','["repairing engines", "creating animated titles and effects", "preparing tax returns", "teaching swim lessons"]'::jsonb,1,'Motion artists build animated visuals.','original'),
('127.683.d.1.B',3,'A student interested in video production can learn which skills are needed by:','["guessing", "avoiding research", "reading job postings and career profiles", "ignoring requirements"]'::jsonb,2,'Postings list skills and education.','original'),
('127.683.d.1.B',4,'After researching a media career, the best next step is to:','["skip planning", "pick a different subject each week", "forget the research", "list the classes and skills needed to reach it"]'::jsonb,3,'Research should lead to a plan.','original'),
('127.683.d.1.C',3,'A portfolio is mainly used to:','["show examples of a person''s best work", "store passwords", "track hours worked", "list grocery items"]'::jsonb,0,'Portfolios showcase skills.','original'),
('127.683.d.1.C',4,'A resume differs from a portfolio because a resume:','["contains only photos", "summarizes experience while a portfolio shows actual work", "is never read", "shows videos only"]'::jsonb,1,'Resumes summarize; portfolios demonstrate.','original'),
('127.683.d.1.D',3,'A digital portfolio can be shared easily with employers by using a:','["paper envelope only", "bulletin board", "website or online link", "fax machine only"]'::jsonb,2,'Online portfolios are easy to share.','original'),
('127.683.d.1.D',4,'Which item belongs in a digital portfolio for a graphic design job?','["grocery lists", "unfinished doodles with no context", "private passwords", "samples of finished logos and layouts"]'::jsonb,3,'Include polished, relevant work.','original'),
('127.683.d.2.A',3,'Which technology allows a team to share messages in real time?','["an online chat room", "a paper note", "a postcard", "a bulletin"]'::jsonb,0,'Chat allows live communication.','original'),
('127.683.d.2.A',4,'A team editing a shared online document at the same time is using:','["a projector", "collaboration software", "a calculator", "a scanner"]'::jsonb,1,'Shared tools support teamwork.','original'),
('127.683.d.2.B',3,'A good way to find free-to-use images online is to search for:','["private photos", "only paid stock", "images licensed for reuse", "any image at all"]'::jsonb,2,'License filters protect users.','original'),
('127.683.d.2.B',4,'Putting quotation marks around a phrase in a search tells the engine to find:','["only videos", "unrelated words", "nothing", "that exact phrase"]'::jsonb,3,'Quotes force exact matching.','original'),
('127.683.d.2.C',3,'Virtual reality headsets and 360-degree video are examples of:','["recent digital media technology", "radio towers", "old print media", "ancient art"]'::jsonb,0,'They are modern immersive media.','original'),
('127.683.d.2.C',4,'A trend in digital media is delivering content through:','["carrier pigeons", "streaming services", "telegrams", "film reels only"]'::jsonb,1,'Streaming is a major delivery method.','original'),
('127.683.d.2.D',3,'Choosing software for editing video should depend mainly on:','["the fonts on the box", "the box color", "what the project requires", "the price of unrelated items"]'::jsonb,2,'Fit to the task drives selection.','original'),
('127.683.d.2.D',4,'For a project that needs layered photo editing, the best software type is:','["presentation timer", "spreadsheet software", "file backup software", "image editing software"]'::jsonb,3,'Photo editors support layers.','original'),
('127.683.d.3.A',3,'Using someone else''s photo as your own without permission is:','["unethical", "acceptable", "encouraged", "required"]'::jsonb,0,'Taking credit for others'' work is wrong.','original'),
('127.683.d.3.A',4,'Ethical use of online resources includes:','["deleting credits", "giving credit to creators", "copying for profit", "hiding sources"]'::jsonb,1,'Crediting respects creators.','original'),
('127.683.d.3.B',3,'A student may quote a short passage from a book in a school review under the idea of fair use. Fair use is meant for purposes like:','["claiming it as your own", "selling copies", "education and criticism", "hiding the source"]'::jsonb,2,'Fair use covers certain limited uses.','original'),
('127.683.d.3.B',4,'A photographer applies a Creative Commons license to a photo. This lets the photographer:','["charge reuse fees", "ban all sharing", "hide their names", "share their work with set conditions for reuse"]'::jsonb,3,'CC licenses define reuse terms.','original'),
('127.683.d.3.C',3,'Before using a song in a video that will be sold, you should get:','["permission or a license", "a guess", "nothing", "a joke"]'::jsonb,0,'Commercial use needs rights.','original'),
('127.683.d.3.C',4,'Posting a full copyrighted movie online without permission:','["is open source", "breaks copyright law", "follows the law", "is fair use"]'::jsonb,1,'Unauthorized sharing is infringement.','original'),
('127.683.d.3.D',3,'A company''s name and logo are shielded from copycats by which legal protection?','["a warranty", "a lease", "a trademark", "a patent"]'::jsonb,2,'Trademarks protect brand identifiers.','original'),
('127.683.d.3.D',4,'Which kind of work is automatically covered the moment its creator records it?','["product names only", "company slogans only", "street names", "original creative works such as songs and images"]'::jsonb,3,'Copyright covers creative expression.','original'),
('127.683.d.3.E',3,'Intellectual property refers to:','["creations of the mind such as inventions and art", "machines only", "money only", "physical land"]'::jsonb,0,'IP includes creative and inventive works.','original'),
('127.683.d.3.E',4,'An inventor who creates a new machine can apply for what protection?','["a lease", "a patent", "a warranty", "a library card"]'::jsonb,1,'Patents cover inventions.','original'),
('127.683.d.3.F',3,'Accessing a school''s grade system without permission is:','["backup", "tutoring", "hacking", "research"]'::jsonb,2,'Unauthorized access is hacking.','original'),
('127.683.d.3.F',4,'Copying and sharing paid software for free is called:','["publishing", "mirroring", "sketching", "piracy"]'::jsonb,3,'Unauthorized copying is piracy.','original'),
('127.683.d.3.G',3,'When using information from a website in a report, you should:','["cite the source", "claim it as yours", "hide it", "delete the link"]'::jsonb,0,'Citations give credit and prove sources.','original'),
('127.683.d.3.G',4,'A proper citation for a website usually includes the title, the author and the:','["weather", "URL and date accessed", "price", "color"]'::jsonb,1,'These details help readers find the source.','original'),
('127.683.d.3.H',3,'A non-disclosure agreement (NDA) is used to:','["share secrets", "sell software", "keep certain information confidential", "promote products"]'::jsonb,2,'NDAs protect confidential information.','original'),
('127.683.d.3.H',4,'A freelance designer signs an agreement stating who owns the finished work. This is an:','["lease", "lunch agreement", "parking permit", "intellectual property agreement"]'::jsonb,3,'IP agreements assign ownership.','original'),
('127.683.d.4.A',3,'A poster is a printed product while a website is a:','["digital product", "paper product", "sculpture", "song"]'::jsonb,0,'Websites are digital.','original'),
('127.683.d.4.A',4,'Compared with a printed flyer, a digital ad can easily include:','["only static text", "motion and interactive elements", "nothing visual", "only paper texture"]'::jsonb,1,'Digital media can animate and respond.','original'),
('127.683.d.4.B',3,'Adding shadows beneath an object in a design helps create:','["blank space", "flat shapes", "a sense of depth", "missing parts"]'::jsonb,2,'Shadows suggest depth.','original'),
('127.683.d.4.B',4,'Making distant objects smaller and lighter helps show:','["alignment", "rhythm", "typography", "perspective"]'::jsonb,3,'Atmospheric perspective implies distance.','original'),
('127.683.d.4.C',3,'Balance in a design means the visual weight is:','["distributed evenly across the layout", "all on one corner", "always black", "always blank"]'::jsonb,0,'Balance spreads weight.','original'),
('127.683.d.4.C',4,'Using one dominant large image to draw the eye first applies the principle of:','["repetition", "emphasis", "proportion", "unity"]'::jsonb,1,'Emphasis directs attention.','original'),
('127.683.d.4.D',3,'In a picture, the area closest to the viewer is the:','["skyline", "horizon", "foreground", "background"]'::jsonb,2,'Foreground is nearest.','original'),
('127.683.d.4.D',4,'Placing objects in the foreground, middle ground and background creates:','["a blank page", "a flat image", "an error", "a layered feeling of depth"]'::jsonb,3,'Layers add dimension.','original'),
('127.683.d.4.E',3,'The style and appearance of letters is called:','["typography", "choreography", "geography", "photography"]'::jsonb,0,'Typography covers fonts and lettering.','original'),
('127.683.d.4.E',4,'Using too many different fonts in one layout usually makes it look:','["clean and simple", "cluttered and hard to read", "professional", "empty"]'::jsonb,1,'Consistency improves readability.','original'),
('127.683.d.4.F',3,'Red, yellow and blue are known as:','["secondary colors", "tertiary shades", "primary colors", "neutral colors"]'::jsonb,2,'These are the traditional primaries.','original'),
('127.683.d.4.F',4,'Colors opposite each other on the color wheel are called:','["neutral colors", "monochrome colors", "analogous colors", "complementary colors"]'::jsonb,3,'Complements sit opposite.','original'),
('127.683.d.4.G',3,'Before finalizing a design, a good practice is to:','["gather feedback and revise", "ignore opinions", "skip review", "delete drafts"]'::jsonb,0,'Revision improves quality.','original'),
('127.683.d.4.G',4,'Aligning text and images to a grid makes a layout look:','["broken", "orderly and consistent", "unfinished", "random"]'::jsonb,1,'Grids create structure.','original'),
('127.683.d.5.A',3,'Raster images are made of:','["text", "mathematical paths", "tiny colored squares called pixels", "sound waves"]'::jsonb,2,'Bitmaps use pixels.','original'),
('127.683.d.5.A',4,'A key advantage of vector graphics is that they:','["cannot be edited", "only work on paper", "lose quality when enlarged", "scale to any size without losing sharpness"]'::jsonb,3,'Vectors use math paths.','original'),
('127.683.d.5.B',3,'Which program type is best for drawing a logo that must scale cleanly?','["vector illustration software", "spreadsheet", "calendar", "word counter"]'::jsonb,0,'Vector tools make scalable art.','original'),
('127.683.d.5.B',4,'Retouching a photograph is best done in:','["a database", "raster-based image editing software", "a chat client", "a vector logo tool"]'::jsonb,1,'Photos are pixel-based.','original'),
('127.683.d.5.C',3,'A graphic meant for a website is usually exported at:','["print resolution always", "zero resolution", "a lower resolution suited to screens", "random resolution"]'::jsonb,2,'Web images are optimized for screens.','original'),
('127.683.d.5.C',4,'Preparing an image for professional printing generally requires a resolution of about:','["1 dot per inch", "5 dots per inch", "10 dots per inch", "300 dots per inch"]'::jsonb,3,'300 dpi is the print standard.','original'),
('127.683.d.5.D',3,'Increasing an image''s resolution generally makes the file:','["larger", "unreadable", "empty", "smaller"]'::jsonb,0,'More pixels mean more data.','original'),
('127.683.d.5.D',4,'A photograph with many colors is best saved as a:','["spreadsheet", "JPEG", "MIDI", "plain text"]'::jsonb,1,'JPEG handles photos efficiently.','original'),
('127.683.d.5.E',3,'A file ending in .png is typically a:','["program", "song", "raster image", "video"]'::jsonb,2,'PNG is an image format.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
