('127.684.d.5.C',3,'Which is a strong way to protect your online accounts?','["use a unique password for each account", "share your passwords", "write it on a public note", "use the same password everywhere"]'::jsonb,0,'Unique passwords limit damage.','original'),
('127.684.d.5.C',4,'Giving out your home address in a public forum is risky because it can:','["protect you", "let strangers find where you live", "earn rewards", "improve your reputation"]'::jsonb,1,'Limit personal information online.','original'),
('127.684.d.5.D',3,'Using licensed media and giving credit are examples of:','["unsafe behavior", "risky actions", "legal and responsible technology use", "illegal habits"]'::jsonb,2,'Responsible use follows law.','original'),
('127.684.d.5.D',4,'A student who tells classmates about phishing scams is practicing:','["trouble-making", "secrecy", "gossip", "advocacy for safe technology use"]'::jsonb,3,'Advocating spreads safe habits.','original'),
('127.684.d.6.A',3,'A scanner is a device that:','["converts paper images into digital files", "prints pages", "charges phones", "plays music"]'::jsonb,0,'Scanners digitize paper.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_85_v1'
from (values
('127.684.d.6.A',4,'A device that captures video and sends it live over the internet is a:','["projector", "webcam", "scanner", "printer"]'::jsonb,1,'Webcams stream video.','original'),
